export const photo = (id: PhotoId) => manifest[id];

export const srcSet = (id: PhotoId) =>
  manifest[id].widths.map((w) => `/images/${id}-${w}.webp ${w}w`).join(', ');

/** The smallest variant at least `width` wide, or the largest there is. */
export const src = (id: PhotoId, width = 1600) => {
  const widths = manifest[id].widths;
  return `/images/${id}-${widths.find((w) => w >= width) ?? widths[widths.length - 1]}.webp`;
};
